local a={}a.__index=a;function a.new()return setmetatable({com={fwd=0,right=0,span=0}},a)end;function a:setCom(b)b=b or{}self.com={fwd=tonumber(b.fwd)or 0,right=tonumber(b.right)or 0,span=tonumber(b.span)or 0}return self end;function a.offsetFromDuties(c,d)d=d or 0;if not c or d<0.05 then return{fwd=0,right=0}end;local e=((c.FL or 0)+(c.FR or 0)+(c.RL or 0)+(c.RR or 0))/4;if math.abs(e)<1e-6 then return{fwd=0,right=0}end;local f=((c.FL or 0)+(c.FR or 0))/2-e;local g=((c.FL or 0)+(c.RL or 0))/2-e;return{fwd=d*f/e,right=-d*g/e}end;local function h(i)if i<0 then return 0 elseif i>1 then return 1 else return i end end;local j={YFL=1,YFR=-1,YRL=-1,YRR=1}local k={YFL=1,YFR=-1,YRL=1,YRR=-1}local l={YRL=-1,YRR=1}function a:mixLateral(m,n,o)local p={}for q,r in pairs(j)do p[q]=h((k[q]or 0)*(m or 0)+r*(n or 0)+(l[q]or 0)*(o or 0))end;return p end;function a:mixYaw(n)return self:mixLateral(0,n)end;function a:mixSurge(s)s=s or 0;return{MAIN=s>0 and h(s)or 0,FRL=s<0 and h(-s)or 0,FRR=s<0 and h(-s)or 0}end;local function t(e,f,g,b)local u=b and b.span or 0;if u<0.05 then return e+f+g,e+f-g,e-f+g,e-f-g end;local v=u*0.9;local w=b.fwd or 0;local x=b.right or 0;if w>v then w=v elseif w<-v then w=-v end;if x>v then x=v elseif x<-v then x=-v end;local y=(u+w)/u;local z=(u-w)/u;local A=(u-x)/u;local B=(u+x)/u;return e*y*A+f+g,e*y*B+f-g,e*z*A-f+g,e*z*B-f-g end;local function C(e,f,g,b)local D,E,F,G=t(e,f,g,b)local H=math.min(D,E,F,G)local I=math.max(D,E,F,G)local J=I-H;if J>1 then local K=1/J;f,g=f*K,g*K;D,E,F,G=t(e,f,g,b)H=math.min(D,E,F,G)I=math.max(D,E,F,G)end;local L=0;if H<0 then L=-H elseif I>1 then L=1-I end;return h(D+L),h(E+L),h(F+L),h(G+L)end;function a:mix(c)local D,E,F,G=C(c.heave or 0,c.pitch or 0,c.roll or 0,self.com)local p={FL=D,FR=E,RL=F,RR=G}for q,M in pairs(self:mixLateral(c.sway,c.yaw,c.yawRear))do p[q]=M end;for q,M in pairs(self:mixSurge(c.surge))do p[q]=M end;return p end;return a